                            let r = calc_we_column_total( frm, all_roles, period, !frm.hide_plan );

                            let total_plan = r.plan;

                            let total_actual = r.actual;



                            let delta = total_plan ? (((total_actual - total_plan) / total_plan) * 100).toFixed(1)  : 0;



