                                <div class="we-group-actual"><span class="readonly-fact">${total_actual.toFixed(1)}</span></div>

                                ${cur_frm.hide_delta ? "" : `<div class="we-group-delta"><span>${Number.parseFloat( delta ).toFixed(1)}%</span></div>`}

                              </div>`;

                        }

                    }

                    return "";

                }

