                                all_hours: fact,

                                year: period.year,

                                month: period.month

                            });

                        });

                    });

                });



                // Функция продолжения загрузки

                function doContinue() {

                    let table_data = tasksArray;

                    let visibleRows;



                    if (updateRows) {

                        visibleRows = frm.work_efforts_dt.bodyRenderer.visibleRowIndices;

