                        }



                        console.timeEnd("load_work_efforts_data_optimized");



                        frm.last_loaded_project = frm.doc.name;

                        frm.last_loaded_time = new Date();

                    });

                }



                if (periodPositions.length > 0) {

                    frappe.call({

                        method: 'calculate_timesheet_limits',

                        args: {

                            timesheet_name: '',

                            positions: periodPositions

                        },

                        callback: function(r) {

                            if (r.message) {

                                frm.periodLimitStatuses = {};

                                r.message.forEach(item => {

