/**
 * Формирование описания колонок таблицы
 */
function get_columns_definition(frm, periodType, unit) {
    let columns = [];
    let allRoles = get_project_roles(frm);

    // 1. Колонка "Задачи"
    columns.push({
        name: __("Задачи"),
        id: "subject",
        width: 250,
        sortable: false,
        dropdown: false,
        editable: false,
        focusable: false,
        treeView: true,
        format: (value, row, column, data) => {
            let taskId = data?.value;
            let missingRoles = frm._missingPlanMap?.[taskId];
            
            // Оборачиваем в div с data-task-id --- нужно для поиска что сврочаиваем в expandParents
            let html = `<div data-task-id="${taskId}"`;
            
            if (missingRoles && missingRoles.length > 0) {
                let rolesList = missingRoles.join(", ");
                let tooltipText = __("Не определены трудозатраты для ролей: {0}", [rolesList]);
                html += `class="missing-plan-task" data-tooltip="${tooltipText}"`;
            }
            
            html += '>';
            html += data?.subject || value;
            html += `</div>`;
            return html;
        }
    });
    
    // 2. Колонка "Роли"
    columns.push({
        name: "Роли",
        id: "role",
        width: 220,
        sortable: false,
        editable: false,
        focusable: false,
        dropdown: false,
        format: (value, row, column, data) => {
            let roleLines = "";
            
            if (data) {
                let taskId = data.value;
                let missingRoles = frm._missingPlanMap?.[taskId] || [];
                
                let role_data = data.role_data || [];
                role_data = role_data.sort((a, b) => (a.role.localeCompare(b.role)));
                
                role_data.forEach(r => {
                    let isMissing = missingRoles.includes(r.role);
                    let tooltipAttr = isMissing ? ` data-tooltip="${__("Не определены трудозатраты для роли: {0}", [r.role])}"` : '';
                    
                    roleLines += `<div class='we-role ${ isMissing ? "miss-plan" : "" }' ${tooltipAttr}>`;
                    roleLines += r.role ? __(r.role) : "-";
                    
                    // Delete Button
                    let hasFact = false;
                    for (const key in r) {
                        if (key.startsWith("fact_") && parseFloat(r[key]) > 0) {
                            hasFact = true;
                            break;
                        }
                    }
                    if (r.role && !hasFact) {
                        roleLines += `<button data-task="${data.value}" data-role="${r.role}"
                            class="btn delete-role-btn btn-default btn-sm filter-x-button" title="Удалить роль">
                            <span class="filter-icon">
                                <svg class="es-icon es-line icon-sm" aria-hidden="true">
                                    <use class="" href="#es-small-close"></use>
                                </svg>
                            </span>
                        </button>`;
                    }
                    roleLines += `</div>`;
                });
                
                // Добавление выпадающего списка с новыми ролями
                let existingRoles = role_data.map(r => r.role);
                let availableRoles = allRoles.filter(r => r && !existingRoles.includes(r));
                if (availableRoles.length > 0) {
                    roleLines += `<div>
                        <select class="new-role-select btn btn-default" data-task="${data.value}"> 
                            <option value="">${__("Добавить роль")}</option>`;
                    availableRoles.forEach(role => {
                        roleLines += `<option value="${role}">${__(role)}</option>`;
                    });
                    roleLines += `</select>
                        </div>`;
                }
            } else if (value) {
                roleLines = value;
            }
            
            return roleLines;
        }
    });
    
    // 3. Колонка "Назначения"
    if (frm.show_assignments) {
        columns.push({
            name: __("Назначения"),
            id: "assignments",
            width: 95,
            sortable: false,
            editable: false,
            focusable: false,
            dropdown: false,
            format: function(value, row, column, data) {
                if (!data || !data.value) return "";
                
                let task_id = data.value;
                let role_data = data.role_data || [];
                
                // Получаем назначения из кэша
                let assignments = get_task_assignments(task_id);
                
                function normalize(str) {
                    return str ? str.trim() : "";
                }
                
                let rolesWithAssignments = {};
                assignments.forEach(assignment => {
                    let role = normalize(assignment.role) || "Без роли";
                    if (!rolesWithAssignments[role]) {
                        rolesWithAssignments[role] = [];
                    }
                    rolesWithAssignments[role].push(assignment);
                });
                
                function getAvatarGroupHtml(users, limit = 3) {
                    if (!users || users.length === 0) return '';
                    try {
                        let userEmails = users.map(u => u.user);
                        let avatarGroup = frappe.avatar_group(userEmails, limit, { filterable: false });
                        if (avatarGroup && avatarGroup.length > 0) {
                            return avatarGroup[0].outerHTML;
                        }
                    } catch (e) {
                        console.error("Ошибка в avatar_group:", e);
                    }
                    return '';
                }
                
                let html = '<div class="assignments-container">';
                
                role_data.forEach((r, idx) => {
                    let role = normalize(r.role);
                    let users = [];
                    
                    if (role && rolesWithAssignments[role]) {
                        users = rolesWithAssignments[role];
                        delete rolesWithAssignments[role];
                    }
                    
                    let avatarHtml = getAvatarGroupHtml(users, 3);
                    
                    html += `<div class="assignment-row" data-task="${task_id}">`;
                    if (avatarHtml) {
                        html += `<div class="assignment-avatars-group">${avatarHtml}</div>`;
                    }
                    html += `</div>`;
                });
                
                let remainingRoles = Object.keys(rolesWithAssignments);
                if (remainingRoles.length > 0) {
                    let allUsers = [];
                    remainingRoles.forEach(role => {
                        allUsers.push(...rolesWithAssignments[role]);
                    });
                    let avatarHtml = getAvatarGroupHtml(allUsers, 3);
                    
                    html += `<div class="assignment-row" data-task="${task_id}">`;
                    if (avatarHtml) {
                        html += `<div class="assignment-avatars-group">${avatarHtml}</div>`;
                    }
                    html += `</div>`;
                }
                
                // Если нет ни одной строки (нет ролей и нет назначений), добавляем пустую строку для кликабельности
                if (role_data.length === 0 && remainingRoles.length === 0) {
                    html += `<div class="assignment-row" data-task="${task_id}"></div>`;
                }
                
                html += '</div>';
                return html;
            }
        });
    }
    
   /*
   Вместо вложенных columns формируем одну колонку, внутри которой вручную выводим три значения.
   Для редактирования (если период текущий или будущий) мы делаем значение "факт/прогноз" кликабельным.
    */
    let periods = get_display_periods(frm, periodType);
    periods.forEach(function(period) {
        // Вычисляем: если период в прошлом – отображаем "факт", иначе "прогноз"
        let subcolumn_label = period.is_past ? __("Факт") : __("Прогноз");
        columns.push({
            name: `<div style="text-align:center;">
                    ${period.year} ${period.month}<br/>
                    <div class="work-efforts-group-header">` +
                        (cur_frm.hide_plan ? "" : `<span>План</span>`) +
                        `<span>${subcolumn_label}</span>` +
                        (cur_frm.hide_delta ? "" : `<span>Δ</span>`) +
                    `</div>
               </div>`,
            id: `group_${period.year}_${period.month}`,
            sortable: false,
            get width() {
                return 200 - (cur_frm.hide_plan ? 65 : 0) - (cur_frm.hide_delta ? 65 : 0);
            },
            dropdown: false,
            focusable: false,
            editable: false,
            format: function(value, row, column, data) {
            let lines = "";
                
                if (data) {
                    let taskId = data.value;
                    let role_data = data.role_data || [];
                    role_data = role_data.sort((a, b) => (a.role.localeCompare(b.role)));
                    
                    // Получаем информацию о проблемных периодах
                    let taskPeriodsMap = frm._missingPlanPeriodsMap?.[taskId] || {};
                    
                    
                    // Проверяем сроки для плана
                    let inPlanDates = isPeriodInTaskDates(period, data.custom_planned_start_date, data.custom_planned_end_date);
                    
                    // Вычисляем даты для факта (с fallback на прогнозные)
                    let factStartDate = data.act_start_date || data.exp_start_date;
                    let factEndDate = data.act_end_date || data.exp_end_date;
                    let inFactDates = isPeriodInTaskDates(period, factStartDate, factEndDate);
                    
                    // Вычисляем даты для прогноза
                    let inForecastDates = isPeriodInTaskDates(period, data.exp_start_date, data.exp_end_date);
                    
                    // Проверяем конфликт: факт в прошлом + прогноз в будущем
                    let today = new Date();
                    let actStart = data.act_start_date ? new Date(data.act_start_date) : null;
                    let actEnd = data.act_end_date ? new Date(data.act_end_date) : null;
                    let expStart = data.exp_start_date ? new Date(data.exp_start_date) : null;
                    
                    let hasFactInPast = (actStart && actEnd && actEnd < today);
                    let hasForecastInFuture = (expStart && expStart >= today);
                    let factAndForecastConflict = hasFactInPast && hasForecastInFuture;
                    
                    // Результирующая заливка
                    let showForecastFill = false;
                    
                    if (frm.view_options === __("Только прогноз")) {
                        showForecastFill = inForecastDates;
                    } else if (frm.view_options === __("Только факт")) {
                        showForecastFill = inFactDates;
                    } else { // "Прогноз и факт"
                        if (factAndForecastConflict) {
                            showForecastFill = inFactDates;
                        } else {
                            if (period.is_past) {
                                showForecastFill = inFactDates;
                            } else {
                                showForecastFill = inForecastDates;
                            }
                        }
                    }
                    //
                    
                    // Классы для колонок
                    let planColumnClass = "we-plan-column";
                    if (inPlanDates) planColumnClass += " in-plan-dates";
                    
                    let actualColumnClass = "we-actual-column";
                    if (inForecastDates) actualColumnClass += " in-forecast-dates";
                    
                    let deltaColumnClass = "we-delta-column";
                    if (inForecastDates) deltaColumnClass += " in-forecast-dates";
                    
                    // Доступные роли (вычисляем один раз)
                    let existingRoles = role_data.map(r => r.role);
                    let availableRoles = allRoles.filter(r => r && !existingRoles.includes(r));
                    
                    // Начинаем контейнер
                    lines += `<div class="we-columns-container" data-year="${period.year}" data-month="${period.month}" data-task="${data.value}">`;
                    
                    // ========== КОЛОНКА ПЛАНА ==========
                    if (!cur_frm.hide_plan) {
                        lines += `<div class="${planColumnClass}">`;
                        
                        role_data.forEach(function(r) {
                            let roleName = r.role || '';
                            let plan = r[`plan_${period.year}_${period.month}`] || 0;
                            
                            let planClasses = "we-role-value";
                            if (plan == 0) planClasses += " zero";
                            
                            let rolePeriods = taskPeriodsMap[roleName];
                            let isMissingPeriod = rolePeriods ? rolePeriods.some(p => p.year == period.year && p.month == period.month) : false;
                            if (isMissingPeriod) planClasses += " missing-plan-highlight";
                            
                            lines += `<div class="${planClasses}" data-role="${roleName}"><span>${plan}</span></div>`;
                        });
                        
                        if (availableRoles.length > 0) {
                            lines += `<div class="we-role-value" data-role=""><span></span></div>`;
                        }
                        
                        lines += `</div>`; // конец колонки плана
                    }
                    
                    // ========== КОЛОНКА ПРОГНОЗА/ФАКТА ==========
                    lines += `<div class="${actualColumnClass}">`;
                    
                    role_data.forEach(function(r) {
                        let roleName = r.role || '';
                        let actual = period.is_past
                                     ? (r[`fact_${period.year}_${period.month}`] || 0)
                                     : (r[`forecast_${period.year}_${period.month}`] || 0);
                        
                        let actualClasses = "we-role-value";
                        if (actual == 0) actualClasses += " zero";
                        
                        let hasWorkload = hasWorkloadInPeriod(frm, taskId, roleName, period);
                        if (hasWorkload) actualClasses += " has-workload";
                        
                        lines += `<div class="${actualClasses}" data-role="${roleName}"><span class="${period.is_past ? "readonly-fact" : "editable-forecast"}">${actual}</span></div>`;
                    });
                    
                    if (availableRoles.length > 0) {
                        lines += `<div class="we-role-value" data-role=""></div>`;
                    }
                    
                    lines += `</div>`; // конец колонки прогноза
                    
                    // ========== КОЛОНКА ДЕЛЬТЫ ==========
                    if (!cur_frm.hide_delta) {
                        lines += `<div class="${deltaColumnClass}">`;
                        
                        role_data.forEach(function(r) {
                            let plan = r[`plan_${period.year}_${period.month}`] || 0;
                            let actual = period.is_past
                                         ? (r[`fact_${period.year}_${period.month}`] || 0)
                                         : (r[`forecast_${period.year}_${period.month}`] || 0);
                            let delta = plan ? (((actual - plan) / plan) * 100).toFixed(1) : 0;
                            
                            let deltaClasses = "we-role-value";
                            if (delta == 0) deltaClasses += " zero";
                            
                            lines += `<div class="${deltaClasses}" data-role="${r.role || ''}"><span>${delta}%</span></div>`;
                        });
                        
                        if (availableRoles.length > 0) {
                            lines += `<div class="we-role-value" data-role=""><span></span></div>`;
                        }
                        
                        lines += `</div>`;
                    }
                    
                    lines += `</div>`; // конец we-columns-container
                } else if (value) {
                    lines = value;
                }
                return lines;
            }
        });
    });
    
    // Добавляем колонку "Итого" – суммарные значения по всем периодам
    columns.push({
        name: `<div style="text-align:center;">
                    ${__("Итого")}<br/>
                    <div class="work-efforts-group-header">` +
                        (cur_frm.hide_plan ? "" : `<span>План</span>`) +
                        `<span>${__("Прогноз")}</span>` +
                        (cur_frm.hide_delta ? "" : `<span>Δ</span>`) +
                    `</div>
               </div>`,
        id: "total",
        get width() {
                return 200 - (cur_frm.hide_plan ? 65 : 0 ) - (cur_frm.hide_delta ? 65 : 0);
            },
        sortable: false,
        dropdown: false,
        focusable: false,
        editable: false,
        format: function(value, row, column, data) {
            
            let lines = "";
            
            if (data) {
                let role_data = data.role_data || [];
                if (role_data.length === 0) {
                    role_data = [{ role: '' }]; // Пустая роль для отображения фона
                }
    
                role_data.forEach(function(r) {
                    let total_plan = 0, total_forecast = 0;
                    
                    periods.forEach(function(period) {
                        let p = parseFloat(r[`plan_${period.year}_${period.month}`]) || 0;
                        total_plan += p;
                        if (period.is_past) {
                            let f = parseFloat(r[`fact_${period.year}_${period.month}`]) || 0;
                            total_forecast += f;
                        } else {
                            let f = parseFloat(r[`forecast_${period.year}_${period.month}`]) || 0;
                            total_forecast += f;
                        }
                    });
                    let delta = total_plan ? (((total_forecast - total_plan) / total_plan) * 100).toFixed(1)  : 0;
                     lines += `<div class="work-efforts-group" 
                            data-task="${data.value}"
                            data-role="${r.role || ''}">
                            ${cur_frm.hide_plan ? "" : `<div class="we-group-plan"><span>${total_plan.toFixed(1)}</span></div>`}
                            <div class="we-group-actual"><span class="readonly-fact">${total_forecast.toFixed(1)}</span></div>
                            ${cur_frm.hide_delta ? "" : `<div class="we-group-delta"><span>${Number.parseFloat(delta).toFixed(1)}%</span></div>`}
                          </div>`;
                });
            }else if ( value ) {
                lines = value;
            }
            
            return lines;
        }
    });

    return columns;
}

// Обработчик для выбора новой роли из выпадающего списка
$(document).on('change', '.new-role-select', function(e) {
    let newRole = $(this).val();
    if (!newRole) return;
    
    let task = $(this).data('task');
    
    // Получаем агрегированные данные из cur_frm
    let aggregatedTasks = cur_frm.aggregatedTasks || {};
    
    // Находим задачу в массиве по value
    let taskData = null;
    if (Array.isArray(aggregatedTasks)) {
        taskData = aggregatedTasks.find(t => t && t.value === task);
    } else {
        taskData = aggregatedTasks[task];
    }
    
    if (taskData) {
        // Проверяем, существует ли уже такая роль
        let role_data = taskData.role_data || [];
        let exists = role_data.some(r => r && r.role === newRole);
        
        if (!exists) {
            // Сначала создаем документ Project Work Efforts на сервере
            frappe.db.get_list("Project Work Efforts", {
                filters: {
                    pwe_project: cur_frm.doc.name,
                    pwe_task: task,
                    pwe_project_role: newRole
                },
                fields: ["name"],
                limit: 1
            }).then(result => {
                if (result && result.length > 0) {
                    return Promise.resolve(result[0]);
                } else {
                    let new_doc = {
                        doctype: "Project Work Efforts",
                        pwe_project: cur_frm.doc.name,
                        pwe_task: task,
                        pwe_project_role: newRole
                    };
                    return frappe.db.insert(new_doc);
                }
            }).then(() => {
                // Теперь добавляем роль в локальные данные
                if (!taskData.role_data) {
                    taskData.role_data = [];
                }
                taskData.role_data.push({ role: newRole });
                
                // ОЧИСТКА КЭША НАЗНАЧЕНИЙ
                clear_assignments_cache();
                
                // Очищаем кэш
                if (cur_frm._tasksByParent) {
                    cur_frm._tasksByParent = null;
                }
                clearTaskIndexCacheFor(cur_frm.aggregatedTasks);
                
                // Обновляем таблицу
                //updateTable(cur_frm, "month", "hours");
                
                // Если колонка "Назначения" включена, перезагружаем назначения
                buildWorkloadPeriodsMap(cur_frm).then(() => {
                    if (cur_frm.show_assignments) {
                        load_all_assignments_if_needed(cur_frm).then(() => {
                            updateTable(cur_frm, "month", "hours");
                        });
                    } else {
                        updateTable(cur_frm, "month", "hours");
                    }
                });
                
                frappe.show_alert({
                    message: __('Роль {0} добавлена', [newRole]),
                    indicator: 'green'
                }, 3);
            }).catch(err => {
                console.error("Ошибка при создании Project Work Efforts:", err);
                frappe.msgprint(__("Ошибка при добавлении роли"));
            });
        } else {
            updateTable(cur_frm, "month", "hours");
        }
    }
});

// Обработчик для удаления роли
$(document).on('click', '.delete-role-btn', function(e) {
    e.stopPropagation();
    let btn = $(this);
    let task = btn.data("task");
    let role = btn.data("role");
    
    frappe.confirm(
        __("Вы действительно хотите удалить роль {0} для задачи {1}?", [role, task]),
        () => {
            console.log(`=== УДАЛЕНИЕ РОЛИ ===`);
            console.log(`Задача: ${task}, Роль: "${role}"`);
            
            // Удаляем из Project Work Efforts
            frappe.db.get_list("Project Work Efforts", {
                filters: {
                    pwe_project: cur_frm.doc.name,
                    pwe_task: task,
                    pwe_project_role: role
                },
                fields: ["name", "pwe_project_role"],
                limit: 10
            }).then(result => {
                console.log(`Найдено PWE для роли "${role}":`, result);
                
                if (result && result.length > 0) {
                    // Удаляем все найденные документы
                    let deletePromises = result.map(doc => {
                        console.log(`Удаляем PWE: ${doc.name}, роль: ${doc.pwe_project_role}`);
                        return frappe.call({
                            method: 'frappe.client.delete',
                            args: {
                                doctype: "Project Work Efforts",
                                name: doc.name
                            }
                        });
                    });
                    return Promise.all(deletePromises);
                } else {
                    console.warn(`PWE для роли "${role}" не найден!`);
                    
                    // Попробуем найти все PWE для задачи и посмотреть, какие роли там есть
                    return frappe.db.get_list("Project Work Efforts", {
                        filters: {
                            pwe_project: cur_frm.doc.name,
                            pwe_task: task
                        },
                        fields: ["name", "pwe_project_role"],
                        limit: 100
                    }).then(allDocs => {
                        console.log(`Все PWE для задачи ${task}:`, allDocs);
                        return Promise.resolve();
                    });
                }
            }).then(() => {
                console.log(`=== ОБНОВЛЕНИЕ ЛОКАЛЬНЫХ ДАННЫХ ===`);
                
                // Обновляем локальные данные - находим задачу в массиве
                let aggregatedTasks = cur_frm.aggregatedTasks || [];
                let taskData = null;
                
                if (Array.isArray(aggregatedTasks)) {
                    taskData = aggregatedTasks.find(t => t && t.value === task);
                } else {
                    taskData = aggregatedTasks[task];
                }
                
                if (taskData && taskData.role_data) {
                    console.log(`Роли до удаления:`, taskData.role_data.map(r => r.role));
                    taskData.role_data = taskData.role_data.filter(r => r.role !== role);
                    console.log(`Роли после удаления:`, taskData.role_data.map(r => r.role));
                } else {
                    console.warn(`taskData или role_data не найдены!`);
                }
                
                // ОЧИСТКА КЭША НАЗНАЧЕНИЙ
                clear_assignments_cache();
                
                // Очищаем кэш
                if (cur_frm._tasksByParent) {
                    cur_frm._tasksByParent = null;
                }
                clearTaskIndexCacheFor(cur_frm.aggregatedTasks);
                
                // Обновляем таблицу с сохранением иерархии
                console.log(`=== ОБНОВЛЕНИЕ ТАБЛИЦЫ ===`);
                
                // Если колонка "Назначения" включена, перезагружаем назначения
                buildWorkloadPeriodsMap(cur_frm).then(() => {
                    if (cur_frm.show_assignments) {
                        load_all_assignments_if_needed(cur_frm).then(() => {
                            updateTable(cur_frm, "month", "hours");
                        });
                    } else {
                        updateTable(cur_frm, "month", "hours");
                    }
                });
                
                frappe.show_alert({
                    message: __('Роль удалена'),
                    indicator: 'green'
                }, 3);
            }).catch(err => {
                console.error("Ошибка при удалении роли:", err);
                frappe.msgprint(__("Ошибка при удалении роли"));
            });
        }
    );
});

// При клике по значению "факт/прогноз" (если редактирование разрешено)
$(document).on('click', '.we-group-actual .editable-forecast', function(e) {
    // Если уже в режиме редактирования, не обрабатываем повторный клик
    if ($(this).find('input').length > 0) return;

    let $span = $(this);
    let currentValue = $span.text().trim();

    let $input = $(`<input type="number" min="0" class="we-edit-input">`)
        .val(currentValue)
        .data('original-value', currentValue);

    $span.html($input);
    $input.focus();
});

/* Функция расчёта суммы прогнозных трудозатрат у дочерних задач */
function get_child_forecast_sum(taskId, role, period, aggregatedTasks) {
    let sum = 0;
    Object.values(aggregatedTasks).forEach(child => {
        if (child.parent_task === taskId) {
            // Для данного дочернего элемента ищем запись по роли
            let childRoleEntry = (child.role_data || []).find(r => r.role === role);
            let forecastKey = `forecast_${period.year}_${period.month}`;
            let childForecast = childRoleEntry ? parseFloat(childRoleEntry[forecastKey]) || 0 : 0;
            if (childForecast > 0) {
                sum += childForecast;
            } else {
                // Если прямые данные отсутствуют, пробуем рекурсивно получить сумму из его потомков
                sum += get_child_forecast_sum(child.value, role, period, aggregatedTasks);
            }
        }
    });
    return sum;
}

/* Функция для определения максимального допустимого значения в дочерней задаче */
function get_parent_forecast_limit(taskId, role, period, aggregatedTasks) {
    // Начинаем с непосредственного родителя текущей задачи
    let currentTask = aggregatedTasks[taskId];
    let excluded = [];
    while (currentTask && currentTask.parent_task) {
        excluded.push( currentTask.value );
        let parent = aggregatedTasks[currentTask.parent_task];
        if (parent) {
            let parentRoleEntry = (parent.role_data || []).find(r => r.role === role);
            let forecastKey = `forecast_${period.year}_${period.month}`;
            let parentForecast = parentRoleEntry ? parseFloat(parentRoleEntry[forecastKey]) || 0 : 0;
            if (parentForecast > 0) {
                // Суммируем прогнозные трудозатраты для всех детей родителя (за исключением текущей ветки)
                let siblingsSum = get_child_forecast_sum(
                    parent.value, 
                    role, 
                    period, 
                    Object.values(aggregatedTasks).filter( function( el ) { return excluded.indexOf( el.value ) < 0; } )
                );
                let maxAllowed = parentForecast - siblingsSum;
                return maxAllowed;
            }
        }
        currentTask = parent; // поднимаемся вверх по дереву
    }
    return null;
}

// При потере фокуса input – сохраняем значение
$(document).on('blur', '.we-edit-input', function(e) {
    let $input = $(this);
    let new_value = parseFloat($input.val());

    let original_value = $input.data('original-value');
    if (new_value == original_value) {
        $input.parent().text(original_value);
        return;
    }

    // Пробуем найти данные через новую структуру
    let $container = $input.closest('.we-columns-container');
    let $roleValue = $input.closest('.we-role-value');
    let year = $container.data('year');
    let month = $container.data('month');
    let task = $container.data('task');
    let role = $roleValue.data('role');
    
    // Если не нашли — пробуем старую структуру
    if (!task) {
        let $group = $input.closest('.work-efforts-group');
        year = $group.data('year');
        month = $group.data('month');
        task = $group.data('task');
        role = $group.data('role');
    }
    
    let period = { year: year, month: month };
    
    // Получаем агрегированные данные
    let aggregatedTasks = cur_frm.aggregatedTasks || {};
    
    // Определяем, является ли текущая задача родительской (есть ли дочерние задачи)
    let isParent = Object.values(aggregatedTasks).some(t => t.parent_task === task);
    if (isParent) {
        let childrenSum = get_child_forecast_sum(task, role, period, aggregatedTasks);
        if (new_value < childrenSum) {
            frappe.msgprint(__("Значение не может быть меньше суммы трудозатрат дочерних задач (" + childrenSum + ")"));
            $input.addClass("error");
            return;
        }
    }
    
    let parentLimit = get_parent_forecast_limit(task, role, period, aggregatedTasks);
    if (parentLimit !== null && (new_value > parentLimit) ) {
        frappe.msgprint(__("Значение трудозатрат не может превышать " + parentLimit + " (ограничение родительской задачи)"));
        $input.addClass("error");
        return;
    }
    
    $input.parent().text(new_value || 0);
    updateForecastValue(task, role, year, month, new_value);
});

/* Пример функции обновления прогнозного значения (согласно ранее реализованной логике) */
function updateForecastValue(task, role, year, month, new_value) {
    frappe.db.get_list("Project Work Efforts", {
        filters: {
            pwe_project: cur_frm.doc.name,
            pwe_task: task,
            pwe_project_role: role
        },
        fields: ["name"],
        limit: 1
    }).then(result => {
        if (result && result.length > 0) {
            return frappe.db.get_doc("Project Work Efforts", result[0].name);
        } else {
            let new_doc = {
                doctype: "Project Work Efforts",
                pwe_project: cur_frm.doc.name,
                pwe_task: task,
                pwe_project_role: role
            };
            return frappe.db.insert(new_doc);
        }
    }).then(doc => {
        let existRow = doc.pwe_amount.find(row => row.pwea_year == year && row.pwea_month == month);
        if (!existRow) {
            let newRow = frappe.model.add_child(doc, "Project Work Efforts Amount", "pwe_amount");
            newRow.pwea_year = year;
            newRow.pwea_month = month;
            newRow.pwea_expected = new_value;
        } else {
            existRow.pwea_expected = new_value;
        }
        return frappe.call({
            method: 'frappe.client.save',
            args: { doc: doc }
        });
    }).then(result => {
        frappe.show_alert({
            message: __('Данные успешно обновлены'),
            indicator: 'green'
        }, 5);
        
        // ОЧИСТКА КЭША НАЗНАЧЕНИЙ
        clear_assignments_cache();
        
        // Находим задачу в массиве aggregatedTasks
        let aggregatedTasks = cur_frm.aggregatedTasks || [];
        let taskData = null;
        
        if (Array.isArray(aggregatedTasks)) {
            taskData = aggregatedTasks.find(t => t && t.value === task);
        } else {
            taskData = aggregatedTasks[task];
        }
        
        if (taskData && taskData.role_data) {
            let roleEntry = taskData.role_data.find(r => r.role === role);
            if (roleEntry) {
                roleEntry[`forecast_${year}_${month}`] = new_value;
            } else {
                // Если роль не найдена, создаем новую запись
                taskData.role_data.push({ 
                    role: role,
                    [`forecast_${year}_${month}`]: new_value 
                });
            }
        }
        
        clearTaskIndexCacheFor(cur_frm.aggregatedTasks);
        buildWorkloadPeriodsMap(cur_frm).then(() => {
            updateTable(cur_frm, "month", "hours");
        });
render_work_efforts_chart(cur_frm, false);
    }).catch(err => {
        frappe.msgprint(__("Ошибка при обновлении прогноза"));
        console.error(err);
    });
}

function save_forecast_as_plan(frm) {
    let periods = get_display_periods(frm, "month");
    let checkedRows = frm.work_efforts_dt.rowmanager.getCheckedRows();
    
    // Собираем данные как массив объектов
    let data = [];
    let hasChanges = false;
    
    for (let i = 0; i < checkedRows.length; i++) {
        let taskObj = frm.work_efforts_dt.datamanager.getData(checkedRows[i]);
        let task = taskObj.value;
        
        if (taskObj.role_data && Array.isArray(taskObj.role_data)) {
            taskObj.role_data.forEach(roleEntry => {
                let role = roleEntry.role || "";
                
                periods.forEach(period => {
                    let new_plan_value = 0;
                    let current_plan = parseFloat(roleEntry[`plan_${period.year}_${period.month}`]) || 0;
                    
                    if (period.is_past) {
                        let factKey = `fact_${period.year}_${period.month}`;
                        new_plan_value = parseFloat(roleEntry[factKey]) || 0;
                    } else {
                        let forecastKey = `forecast_${period.year}_${period.month}`;
                        new_plan_value = parseFloat(roleEntry[forecastKey]) || 0;
                    }
                    
                    // Условие из старой версии: отправляем данные если:
                    // 1. Новое значение отличается от текущего (изменение произошло)
                    // 2. И при этом либо новое > 0, либо текущее > 0 (нужно обнулить)
                    if (new_plan_value !== current_plan && (new_plan_value > 0 || current_plan > 0)) {
                        hasChanges = true;
                        data.push({
                            task: task,
                            role: role,
                            year: period.year,
                            month: period.month,
                            plan_value: new_plan_value,
                            current_plan: current_plan  // Добавляем текущее значение плана
                        });
                    }
                });
            });
        }
    }
    
    if (!hasChanges) {
        frappe.msgprint(__("Нет изменений для сохранения."));
        return;
    }
    
    if (data.length === 0) {
        frappe.msgprint(__("Нет данных для сохранения."));
        return;
    }
    
    frappe.call({
        method: "save_forecast_as_plan",
        args: {
            project: frm.doc.name,
            data: JSON.stringify(data)
        },
        freeze: true,
        freeze_message: __("Сохранение данных..."),
        callback: function(r) {
            if (!r.exc) {
                frappe.show_alert(__("Данные успешно сохранены как план"), 5);
                
                // ОЧИСТКА КЭША НАЗНАЧЕНИЙ
                clear_assignments_cache();
                
                // Сбрасываем кэш загрузки
                frm.last_loaded_time = null;
                frm.last_loaded_project = null;
                
                // Очищаем кэш данных
                clearTaskIndexCacheFor(frm.aggregatedTasks);
                
                // ОЧИСТКА ПОДСВЕТКИ - удаляем карту проблем
                frm._missingPlanMap = {};
                frm._missingPlanPeriodsMap = {};
                
                // Загружаем данные заново с параметром updateRows=true
                load_work_efforts_data(frm, "month", "hours", true);
                
                if (typeof load_and_render_project_dashboard === 'function') {
                    load_and_render_project_dashboard(frm);
                }
            }
        }
    });
}

