  // не плодим дубликаты
  $(grid.wrapper).find('.mn-open-tasks-btn').remove();

  // если поддерживается API грид-кнопок — используем его
  if (grid.add_custom_button) {
    grid.add_custom_button(__('Открыть задачи'), () => open_tasks_for_note(frm), __('Действия'));
    // grid.add_custom_button рендерит в заголовке грида; дубликаты тоже чистим:
    $(grid.wrapper).find('.grid-custom-buttons .btn:contains("Открыть задачи")')
      .addClass('mn-open-tasks-btn');
