  }

  // fallback: добавим кнопку в футер грида, рядом с "Add Row"
  const $btn = $(`<button type="button" class="btn btn-secondary mn-open-tasks-btn" style="margin-left:8px;">${__('Открыть задачи')}</button>`);
  $(grid.wrapper).find('.grid-footer .btn-primary').first().after($btn);
