                filters: {
                    share_doctype: "Project",
                    share_name: frm.doc.name
                },
                fields: ["user", "write", "share"]
            },
            callback: function(response) {
                var existingShares = response.message.map(share => ({
                    user: share.user,
                    write: share.write,
                    share: share.share
                }));
                processUsers(frm, existingShares);
            }
