function processUsers(frm, existingShares) {
    var participants = [];
    
    // Собираем всех участников с типами прав
    $.each(frm.doc.custom_ts_details || [], function(i, d) {
        if (d.pt_participant_type === "User" && d.pt_participant) {
            var role = d.pt_role || "";
            var isManager = role.includes("Руководитель проекта") || role.includes("Администратор проекта");
            
            participants.push({
                user: d.pt_participant,
                write: isManager ? 1 : 0,
                share: isManager ? 1 : 0 // share только для руководителей и администраторов
            });
        }
    });
    
    addParticipantsToProject(participants, frm, existingShares);
}

function addParticipantsToProject(participants, frm, existingShares) {
    // Убираем дубликаты пользователей, сохраняя максимальные права
    let uniqueParticipantsMap = new Map();
    
    participants.forEach(participant => {
        var user = participant.user;
        if (uniqueParticipantsMap.has(user)) {
            // Если уже есть этот пользователь, проверяем права
            var existing = uniqueParticipantsMap.get(user);
            // Обновляем права, если текущий участник имеет более высокие привилегии
            if ((participant.write === 1 && existing.write === 0) ||
                (participant.share === 1 && existing.share === 0)) {
                uniqueParticipantsMap.set(user, {
                    user: user,
                    write: Math.max(existing.write, participant.write),
                    share: Math.max(existing.share, participant.share)
                });
            }
        } else {
            uniqueParticipantsMap.set(user, participant);
        }
    });
    
    let uniqueParticipants = Array.from(uniqueParticipantsMap.values());
    
    // Добавляем только новых участников
    uniqueParticipants.forEach(participant => {
        var existingShare = existingShares.find(share => share.user === participant.user);
        
        if (!existingShare) {
            // Новый участник
            frappe.call({
                method: 'frappe.share.add',
                args: {
                    doctype: 'Project',
                    name: frm.doc.name,
                    user: participant.user,
                    read: 1,
                    write: participant.write,
                    share: participant.share,
                    notify: 1
                },
                callback: function(response) {
                    // Закомментировано: сообщения о добавлении
                    // if (!response.exc) {
                    //     var rights = [];
                    //     if (participant.write === 1) rights.push("запись");
                    //     if (participant.share === 1) rights.push("расшаривание");
                    //     
                    //     var message = rights.length > 0 
                    //         ? __("Добавлен доступ с правами {0} для {1}", [rights.join(", "), participant.user])
                    //         : __("Добавлен доступ только для чтения для {0}", [participant.user]);
                    //     
                    //     frappe.show_alert({
                    //         message: message,
                    //         indicator: 'green'
                    //     }, 3);
                    // }
                }
            });
        } else {
            // Обновляем права существующего участника, если нужно
            updateExistingShare(frm, participant, existingShare);
        }
    });
}

function updateExistingShare(frm, participant, existingShare) {
    var updates = {};
    var updateNeeded = false;
    
    // Проверяем, нужно ли обновлять права
    if (existingShare.write !== participant.write) {
        updates.write = participant.write;
        updateNeeded = true;
    }
    if (existingShare.share !== participant.share) {
        updates.share = participant.share;
        updateNeeded = true;
    }
    
    if (updateNeeded) {
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: "DocShare",
                filters: {
                    share_doctype: "Project",
                    share_name: frm.doc.name,
                    user: participant.user
                },
                fields: ["name"]
            },
            callback: function(response) {
                if (response.message && response.message.length > 0) {
                    var shareDocName = response.message[0].name;
                    
                    frappe.call({
                        method: 'frappe.client.set_value',
                        args: {
                            doctype: 'DocShare',
                            name: shareDocName,
                            fieldname: updates
