function checkUserAffiliation(frm, user) {
    return new Promise((resolve) => {
        if (!user) {
            resolve({ exists: false });
            return;
        }

        frappe.call({
            method: 'check_user_affiliation.process_check',
            args: { user: user },
            callback: ({ message }) => {
                if (!message.is_employee && !message.is_supplier) {
                    frappe.msgprint({
                        title: __('Внимание!'),
                        indicator: 'red',
                        message: __('Участник не найден ни как Сотрудник, ни как Поставщик')
                    });
                }
                resolve(message);
            }
        });
    });
}

