        let pct = r.percent;
        if (pct === null || pct === undefined || pct === '') {
            pct = 0;
        } else if (typeof pct === 'string') {
            pct = parseFloat(pct.replace(',', '.')) || 0;
        } else {
            pct = Number(pct) || 0;
        }
        // аккуратно складываем
        sums[key] = (sums[key] || 0) + pct;
    });

    // Проверяем суммы
    const problems = [];
    Object.keys(sums).forEach(key => {
        const sum = sums[key];
        if (Math.abs(sum - 100) > TOLERANCE) {
            const dateLabel = key === '__NO_DATE__' ? '(без даты valid_from)' : frappe.datetime.obj_to_user(key);
            problems.push(`Сумма % на дату ${dateLabel} равна ${sum.toFixed(2)}% (ожидается 100%).`);
        }
    });

    if (problems.length) {
        if (show_message) {
            frappe.msgprint({
                title: __('Бизнес-сфера проекта: проверка суммы %'),
                message: problems.join('<br>'),
                indicator: 'red'
            });
        }
        return false;
    }
    return true;
}

