                );  
                  
                if (validCostCenterRecords.length > 0) {  
                    // Сортируем по дате и берем ближайшую к referenceDate  
                    validCostCenterRecords.sort((a, b) =>   
                        new Date(b.cct_valid_from) - new Date(a.cct_valid_from)  
                    );  
                      
                    const closestCostCenter = validCostCenterRecords[0];  
                    if (closestCostCenter.cct_cost_center) {  
