frappe.ui.form.on('Sales Invoice', {  
    // Функция для обновления таблицы items после сохранения
    after_save(frm) {
        if (frm.doc.project && frm.doc.cost_center && frm.doc.items && frm.doc.items.length > 0) {
            console.log('Updating items table after save...');
            
            let items_updated = false;
            
            // Обходим все строки в таблице items
            frm.doc.items.forEach(item => {
                // Очищаем поле warehouse во всех строках
                if (item.warehouse) {
                    item.warehouse = null;
                    items_updated = true;
                }
                
                // Устанавливаем project и cost_center в строках
                if (item.cost_center) {
                    if (!item.project) {
                        item.project = frm.doc.project;
                        items_updated = true;
                    }
                    if (item.cost_center) {
                        item.cost_center = frm.doc.cost_center;
                        items_updated = true;
                    }
                }
            });
            
            // Если были изменения, сохраняем форму повторно
            if (items_updated) {
                console.log('Items were updated, saving form again...');
                frm.save();
            } else {
                console.log('No items needed updating');
            }
        }
    }
});

